mkdir -p /tmp/claude-0/-home-user-Claudinite/bf900724-46cc-57bc-88da-75955bb62ea8/scratchpad/logs && cat > /tmp/claude-0/-home-user-Claudinite/bf900724-46cc-57bc-88da-75955bb62ea8/scratchpad/condense.mjs <<'EOF'
// Condense a captured conversation JSONL: human turns in full, assistant text
// trimmed, tool calls to name + first line of input, with timestamps.
import { readFileSync } from 'node:fs';

const [file, mode = 'all'] = process.argv.slice(2);
const lines = readFileSync(file, 'utf8').split('\n').filter(Boolean);
const clip = (s, n) => {
  s = String(s ?? '').replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, n) + '…' : s;
};
for (const line of lines) {
  let e;
  try { e = JSON.parse(line); } catch { continue; }
  const ts = (e.timestamp || '').replace('T', ' ').replace(/\..*/, '');
  const m = e.message;
  if (!m) { if (e.type) console.log(`[${ts}] <${e.type}>`); continue; }
  const role = m.role;
  const content = Array.isArray(m.content) ? m.content : [{ type: 'text', text: m.content }];
  for (const c of content) {
    if (c.type === 'text') {
      if (!c.text?.trim()) continue;
      const cap = role === 'user' ? 100000 : (mode === 'human' ? 0 : 1200);
      if (cap === 0) continue;
      console.log(`[${ts}] ${role.toUpperCase()}: ${clip(c.text, cap)}`);
    } else if (c.type === 'tool_use') {
      if (mode === 'human') continue;
      console.log(`[${ts}]   tool ${c.name}: ${clip(JSON.stringify(c.input), 300)}`);
    } else if (c.type === 'tool_result') {
      if (mode !== 'full') continue;
      const t = Array.isArray(c.content) ? c.content.map(x => x.text || '').join(' ') : c.content;
      console.log(`[${ts}]   result: ${clip(t, 400)}`);
    } else if (c.type === 'thinking') {
      if (mode !== 'full') continue;
      console.log(`[${ts}]   (thinking) ${clip(c.thinking, 600)}`);
    }
  }
}
EOF
