// Print the owner's own prompts from a captured log, plus each assistant text
// turn that directly followed one, so a correction reads with its answer.
import { readFileSync } from 'node:fs';
const [file, cap = '1500'] = process.argv.slice(2);
const N = Number(cap);
const clip = (s, n) => {
  s = String(s ?? '').replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, n) + '…' : s;
};
const seen = new Set();
for (const line of readFileSync(file, 'utf8').split('\n').filter(Boolean)) {
  let e; try { e = JSON.parse(line); } catch { continue; }
  if (e.type === 'last-prompt') {
    const p = clip(e.lastPrompt, 4000);
    if (p && !seen.has(p)) { seen.add(p); console.log(`\n=== OWNER: ${p}\n`); }
    continue;
  }
  const m = e.message;
  if (!m || !Array.isArray(m.content)) continue;
  if (m.role === 'user') {
    for (const c of m.content) if (c.type === 'text' && c.text?.trim()) {
      const p = clip(c.text, 4000);
      if (!seen.has(p)) { seen.add(p); console.log(`\n=== USER-TURN: ${p}\n`); }
    }
  }
  if (m.role === 'assistant') {
    for (const c of m.content) if (c.type === 'text' && c.text?.trim())
      console.log(`  A[${(e.timestamp||'').slice(11,19)}]: ${clip(c.text, N)}`);
  }
}
EOF
echo ok

