{
  "id": "test-suite-command-form",
  "on_fail": "advise",
  "scope": "action",
  "failureMessage": "a bash glob without globstar runs green over a subset \u2014 packs/*/test/*.test.mjs reaches 125 of 314 files and says nothing; node --test <dir> at least fails outright with Cannot find module",
  "fix": "node --test $(git ls-files '*.test.mjs')",
  "guardToolCalls": [
    {
      "tool": "Bash",
      "inputField": "command",
      "match": "/\\bnode\\s+--test\\s+[^\\s;&|]*\\*/",
      "unlessMatches": "/git ls-files/",
      "what": "the suite run through a glob: \"{match}\""
    },
    {
      "tool": "Bash",
      "inputField": "command",
      "match": "/\\bnode\\s+--test\\s*($|[;&|>])/",
      "what": "node --test with no files named"
    }
  ]
}

{
  "id": "commit-all-sweeps-edits",
  "on_fail": "advise",
  "scope": "action",
  "failureMessage": "git commit -a stages every modified file, and a later branch -D discards the in-progress edits it swept up",
  "guardToolCalls": [
    {
      "tool": "Bash",
      "inputField": "command",
      "match": "/(^|[;&|]\\s*|\\n\\s*)git\\s+commit\\b[^;&|\\n]*\\s-a(m)?\\b/",
      "what": "a commit with -a",
      "fix": "stage the files this commit is about by name; isolate pending edits first"
    }
  ]
}

{
  "id": "checkout-restores-index",
  "on_fail": "advise",
  "scope": "action",
  "since": "2026-09-06",
  "failureMessage": "git checkout -- restores from the index, destroying uncommitted work as thoroughly as the mutation it undoes",
  "guardToolCalls": [
    {
      "tool": "Bash",
      "inputField": "command",
      "match": "/(^|[;&|]\\s*|\\n\\s*)git\\s+(checkout\\s+--|restore\\s|stash\\b)/",
      "what": "a working-tree restore: \"{match}\"",
      "fix": "commit or stage the real edit first, and only mutate a file whose current state you are ready to throw away"
    }
  ]
}

{
  "id": "shell-write-to-skill-scoped-path",
  "on_fail": "advise",
  "since": "2026-09-14",
  "scope": "action",
  "failureMessage": "the pre-edit skill guard reads Edit, Write and NotebookEdit only, so a shell write carries its skill requirement to Stop, after the work the skill was there to shape",
  "guardToolCalls": [
    {
      "tool": "Bash",
      "inputField": "command",
      "match": "/(?:>>?\\s*|\\bopen\\(\\s*|\\bPath\\(\\s*|\\b[A-Za-z_]\\w*\\s*=\\s*['\"])['\"]?(?:[\\w.@-]+\\/)*(?:[\\w.@-]+\\.(?:test|spec)\\.\\w+|RULES\\.md|SKILL\\.md|CLAUDE\\.md|tasks\\/[\\w.@\\/-]+|engine\\/checks\\/[\\w.@\\/-]+)/",
      "what": "a skill-scoped file written through the shell: \"{match}\"",
      "fix": "write it with Write, or Edit it after a read \u2014 those are the calls the guard sees"
    }
  ]
}

